const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}
return [{ json: {
  telefono: String(args.telefono || '').trim(),
  fecha_actual: String(args.fecha_actual || '').trim(),
  hora_actual: String(args.hora_actual || '').trim(),
  nueva_fecha: String(args.nueva_fecha || '').trim(),
  nueva_hora: String(args.nueva_hora || '').trim()
}}];

const { telefono, fecha_actual, hora_actual, nueva_fecha, nueva_hora } = $('Parsear Argumentos').first().json;
const filas = $('Google Sheets - Leer Citas').all();

const fila = filas.find(f => {
  const d = f.json;
  const telMatch = String(d['Teléfono'] || '').trim() === telefono;
  const fechaMatch = String(d['Fecha'] || '').trim() === fecha_actual;
  const activa = d['Estado'] === 'CONFIRMADA';
  const horaMatch = !hora_actual || String(d['Hora'] || '').trim() === hora_actual;
  return telMatch && fechaMatch && activa && horaMatch;
});

if (!fila) {
  return [{ json: { encontrado: false, calendarEventId: null, nueva_fecha, nueva_hora }}];
}

const servicio = fila.json['Servicio'];
const DURACIONES = {
  'Revision': 30, 'Limpieza dental': 45, 'Empaste': 45,
  'Extraccion': 30, 'Blanqueamiento dental': 60,
  'Consulta ortodoncia': 30, 'Consulta implantes': 30, 'Endodoncia': 60
};
const duracion = DURACIONES[servicio] || 30;

const nuevaFechaInicio = new Date(`${nueva_fecha}T${nueva_hora}:00`);
const nuevaFechaFin = new Date(nuevaFechaInicio.getTime() + duracion * 60000);

const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

return [{ json: {
  encontrado: true,
  calendarEventId: fila.json['Calendar_Event_ID'],
  nombre: fila.json['Nombre'],
  servicio, telefono, fecha_actual, nueva_fecha, nueva_hora,
  nuevaFechaInicio: nuevaFechaInicio.toISOString(),
  nuevaFechaFin: nuevaFechaFin.toISOString(),
  fechaTexto: `${diasSemana[nuevaFechaInicio.getDay()]} ${nuevaFechaInicio.getDate()} de ${meses[nuevaFechaInicio.getMonth()]}`
}}];

const datos = $('Encontrar Cita en Sheets').first().json;
if (!datos.encontrado) {
  return [{ json: { modificado: false, mensaje: 'No encontré ninguna cita activa para ese teléfono y fecha.' }}];
}
return [{ json: { modificado: true, mensaje: `Listo, tu cita ha quedado cambiada al ${datos.fechaTexto} a las ${datos.nueva_hora}.` }}];
